data class NoteDraft(val title: String, val content: String)

fun validateNote(title: String, content: String): NoteDraft {
    val normalized = title.trim()
    require(normalized.isNotEmpty()) { "标题不能为空" }
    require(normalized.length <= 120) { "标题最多 120 个 UTF-16 单元" }
    require(content.length <= 10_000) { "内容最多 10000 个 UTF-16 单元" }
    return NoteDraft(normalized, content)
}

fun main() {
    check(validateNote("  hello  ", " body ") == NoteDraft("hello", " body "))
    check(validateNote("a".repeat(120), "b".repeat(10_000)).title.length == 120)
    for ((title, body) in listOf("  " to "ok", "a".repeat(121) to "", "ok" to "b".repeat(10_001))) {
        check(runCatching { validateNote(title, body) }.exceptionOrNull() is IllegalArgumentException)
    }
    println("Kotlin note rules passed")
}

import Foundation

struct SavedTask: Codable {
    let id: UUID
    var title: String
    init(id: UUID = UUID(), title: String) {
        self.id = id
        self.title = title
    }
}

final class SharedCounter { var value = 0 }
struct Wrapper { let counter: SharedCounter }

func parseAge(_ raw: String?) -> Int? {
    guard let raw,
          let value = Int(raw.trimmingCharacters(in: .whitespacesAndNewlines)),
          (0...150).contains(value) else { return nil }
    return value
}

let original = SavedTask(title: "learn")
let data = try JSONEncoder().encode(original)
let restored = try JSONDecoder().decode(SavedTask.self, from: data)
precondition(restored.id == original.id)
var edited = restored
edited.title = "practice"
precondition(restored.title == "learn")
let first = Wrapper(counter: SharedCounter())
let second = first
second.counter.value = 3
precondition(first.counter.value == 3)
precondition(parseAge("0") == 0)
precondition(parseAge(" 12 ") == 12)
for invalid: String? in [nil, "", "abc", "-1", "151", "1.5"] {
    precondition(parseAge(invalid) == nil)
}
print("Swift syntax contracts passed")
